1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Step =
11	  | { op: "quote"; items: Item[] }
12	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
13	
14	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
15	
16	export type Result = { premium: number } | { payout: number; remainingCap: number };
17	
18	const PROCESSING_FEE = 5;
19	// Every damage event carries a deductible, borne by the customer.
20	const DEDUCTIBLE_PER_DAMAGE_EVENT = 100;
21	const BASE_PREMIUMS: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	  potion: 40,
26	  rune: 25,
27	  moonstone: 25,
28	};
29	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
30	const LOYALTY_YEARS_THRESHOLD = 2;
31	const LOYALTY_DISCOUNT_RATE = 0.2;
32	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
33	const CURSE_SURCHARGE_RATE = 0.5;
34	const HIGH_ENCHANTMENT_THRESHOLD = 5;
35	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
36	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
37	// A building block of alike components is priced as a unit, not per piece.
38	const COMPONENT_BLOCK_SIZE = 3;
39	const COMPONENT_BLOCK_PREMIUM = 60;
40	// Unmodified insurance value per item; the sum over a policy bounds what can be paid out.
41	const INSURANCE_VALUES: Record<string, number> = {
42	  sword: 1000,
43	  amulet: 600,
44	  rune: 250,
45	};
46	// A policy pays out at most twice its insurance sum.
47	const PAYOUT_CAP_MULTIPLIER = 2;
48	// Damage to strongly enchanted items is only partially reimbursed (a stricter bar than the premium surcharge).
49	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
50	const PARTIAL_REIMBURSEMENT_RATE = 0.5;
51	
52	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
53	
54	const formsBlock = (type: string, count: number): boolean =>
55	  isComponent(type) && count === COMPONENT_BLOCK_SIZE;
56	
57	const premiumForTypeGroup = (type: string, count: number): number =>
58	  formsBlock(type, count) ? COMPONENT_BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
59	
60	const countOfType = (items: Item[], type: string): number =>
61	  items.filter((item) => item.type === type).length;
62	
63	const calculateBasePremium = (items: Item[]): number => {
64	  const types = [...new Set(items.map((item) => item.type))];
65	  return types.reduce(
66	    (total, type) => total + premiumForTypeGroup(type, countOfType(items, type)),
67	    0,
68	  );
69	};
70	
71	// Item-specific modifiers: each applies a rate to the base premium of every affected item.
72	const itemSurcharge = (items: Item[], applies: (item: Item) => boolean, rate: number): number =>
73	  items
74	    .filter(applies)
75	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
76	
77	const isCursed = (item: Item): boolean => item.cursed === true;
78	
79	const isHighlyEnchanted = (item: Item): boolean =>
80	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
81	
82	const curseSurcharge = (items: Item[]): number =>
83	  itemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
84	
85	const enchantmentSurcharge = (items: Item[]): number =>
86	  itemSurcharge(items, isHighlyEnchanted, ENCHANTMENT_SURCHARGE_RATE);
87	
88	// Policy-wide modifiers: each applies to the policy base premium (sum of item base premiums).
89	const firstInsuranceSurcharge = (basePremium: number): number =>
90	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
91	
92	const isLoyalCustomer = (yearsWithMHPCO: number): boolean =>
93	  yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
94	
95	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
96	  isLoyalCustomer(yearsWithMHPCO) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
97	
98	const followUpDiscount = (basePremium: number, isFollowUpContract: boolean): number =>
99	  isFollowUpContract ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
100	
101	// Premiums are rounded up to whole G, in the MHPCO's favour.
102	const roundUpToWholeGold = (amount: number): number => Math.ceil(amount);
103	
104	// What the MHPCO knows about the customer at the moment a quote is issued.
105	type CustomerContext = { yearsWithMHPCO: number; isFollowUpContract: boolean };
106	
107	const quotePremium = (items: Item[], customer: CustomerContext): number => {
108	  const basePremium = calculateBasePremium(items);
109	  const premiumBeforeFee =
110	    basePremium +
111	    curseSurcharge(items) +
112	    enchantmentSurcharge(items) +
113	    firstInsuranceSurcharge(basePremium) -
114	    loyaltyDiscount(basePremium, customer.yearsWithMHPCO) -
115	    followUpDiscount(basePremium, customer.isFollowUpContract);
116	  return roundUpToWholeGold(premiumBeforeFee + PROCESSING_FEE);
117	};
118	
119	const isPartiallyReimbursed = (item: Item | undefined): boolean =>
120	  (item?.enchantment ?? 0) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
121	
122	const reimbursedAmount = (item: Item | undefined, damage: Damage): number =>
123	  isPartiallyReimbursed(item) ? damage.amount * PARTIAL_REIMBURSEMENT_RATE : damage.amount;
124	
125	const findDamagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
126	  insuredItems.find((candidate) => candidate.type === damage.itemType);
127	
128	const payoutForDamage = (insuredItems: Item[], damage: Damage): number =>
129	  reimbursedAmount(findDamagedItem(insuredItems, damage), damage) - DEDUCTIBLE_PER_DAMAGE_EVENT;
130	
131	const claimPayout = (insuredItems: Item[], damages: Damage[]): number =>
132	  damages.reduce((total, damage) => total + payoutForDamage(insuredItems, damage), 0);
133	
134	const insuranceSum = (items: Item[]): number =>
135	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
136	
137	const payoutCap = (items: Item[]): number => insuranceSum(items) * PAYOUT_CAP_MULTIPLIER;
138	
139	const insuredItemsOf = (policyStep: Step): Item[] =>
140	  policyStep.op === "quote" ? policyStep.items : [];
141	
142	const processClaim = (insuredItems: Item[], damages: Damage[], capRemaining: number): Result => {
143	  const payout = Math.min(claimPayout(insuredItems, damages), capRemaining);
144	  return { payout, remainingCap: capRemaining - payout };
145	};
146	
147	// Every contract after the customer's first in a scenario is a follow-up contract.
148	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
149	
150	export const runScenario = (scenario: Scenario): { results: Result[] } => {
151	  const capRemainingByPolicy = new Map<number, number>();
152	  const results = scenario.steps.map((step, index): Result => {
153	    if (step.op === "claim") {
154	      const insuredItems = insuredItemsOf(scenario.steps[step.policy]);
155	      const capRemaining = capRemainingByPolicy.get(step.policy) ?? payoutCap(insuredItems);
156	      const result = processClaim(insuredItems, step.incident.damages, capRemaining);
157	      capRemainingByPolicy.set(step.policy, result.remainingCap);
158	      return result;
159	    }
160	    const customer: CustomerContext = {
161	      yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
162	      isFollowUpContract: isFollowUpContract(index),
163	    };
164	    return { premium: quotePremium(step.items, customer) };
165	  });
166	  return { results };
167	};
